const D = { energy: .6, scale: 1, density: .5, speed: 1, hue: 34, tilt: .5, x: .5, y: .5, style: 'kraft_paper', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const uMin=Math.min(width,height), t=K.t||0;
const fr=i=>{ const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453; return s-Math.floor(s); };

function look(style,hue){
  if(style==='blueprint_crease') return {paper:[214,.50,.22], hi:[190,.30,.80], lo:[220,.55,.14], crease:[188,.60,.92], mv:true, spec:.0, amb:.5, wire:true};
  if(style==='foil_metallic')    return {paper:[hue,.22,.62], hi:[hue+10,.30,.98], lo:[hue-20,.40,.22], crease:[0,0,.20], mv:false, spec:.9, amb:.35, wire:false};
  if(style==='concrete_relief')  return {paper:[36,.06,.50], hi:[36,.05,.78], lo:[220,.10,.14], crease:[0,0,.12], mv:false, spec:.05, amb:.28, wire:false};
  if(style==='washi_indigo')     return {paper:[220,.40,.44], hi:[212,.24,.74], lo:[224,.55,.18], crease:[220,.30,.30], mv:false, spec:.1, amb:.42, wire:false};
  return {paper:[hue,.30,.66], hi:[hue+6,.30,.92], lo:[hue-6,.40,.30], crease:[hue-8,.35,.34], mv:false, spec:.12, amb:.42, wire:false}; // kraft_paper
}
const L=look(P.style,P.hue);

// fold actuation — always-on breathing floor + energy adds; incommensurate => never repeats
const sp=P.speed;
let theta = 0.62 + (0.14 + 0.34*P.energy)*Math.sin(t*0.23*sp) + 0.10*Math.sin(t*0.61*sp+1.1) + 0.06*Math.sin(t*1.09*sp);
theta = Math.max(0.16, Math.min(1.28, theta));
const w = Math.cos(theta), amp = Math.sin(theta)*0.62, skew = Math.sin(theta)*0.42;
const tiltA = 0.62*P.tilt + 0.10*Math.sin(t*0.31*sp+0.4); // viewing tilt, gentle drift
const cT=Math.cos(tiltA), sT=Math.sin(tiltA);
const spin = 0.05*Math.sin(t*0.17*sp) + 0.03*Math.sin(t*0.43*sp+2.0);
const cS=Math.cos(spin), sS=Math.sin(spin);
// light dir (drifts)
let lx=Math.sin(t*0.19*sp+0.5)*0.5, ly=-0.55, lz=0.75; const ll=Math.hypot(lx,ly,lz); lx/=ll; ly/=ll; lz/=ll;

const C=Math.round(10+P.density*22), R=Math.round((10+P.density*22)*0.72);
const cellW=(uMin*1.7*P.scale)/C, cellH=(uMin*1.5*P.scale)/R;
const cx=P.x*width, cy=P.y*height;

// build vertex screen positions + depths
const VX=[],VY=[],VZ=[];
for(let i=0;i<=R;i++){ VX[i]=[];VY[i]=[];VZ[i]=[];
  for(let j=0;j<=C;j++){
    let mx=(j-C/2)*cellW*w + ((i&1)? skew:-skew)*cellW*0.9;
    let my=(i-R/2)*cellH;
    let mz=((j&1)?-1:1)*amp*cellW;
    // gentle field spin in-plane
    const rx=mx*cS - my*sS, ry=mx*sS + my*cS;
    const sy=ry*cT - mz*sT;
    VX[i][j]=cx+rx; VY[i][j]=cy+sy; VZ[i][j]=ry*sT+mz*cT;
  }
}

push();
noStroke();
// backing so no bg shows through gaps
const bg=L.lo; background(bg[0],bg[1]*100,bg[2]*100*0.7);
for(let i=0;i<R;i++) for(let j=0;j<C;j++){
  const ax=VX[i][j],ay=VY[i][j], bx=VX[i][j+1],by=VY[i][j+1];
  const dx=VX[i+1][j+1],dy=VY[i+1][j+1], ex=VX[i+1][j],ey=VY[i+1][j];
  // 3D normal via two edges (use z)
  const e1=[bx-ax,by-ay,VZ[i][j+1]-VZ[i][j]], e2=[ex-ax,ey-ay,VZ[i+1][j]-VZ[i][j]];
  let nx=e1[1]*e2[2]-e1[2]*e2[1], ny=e1[2]*e2[0]-e1[0]*e2[2], nz=e1[0]*e2[1]-e1[1]*e2[0];
  const nl=Math.hypot(nx,ny,nz)||1; nx/=nl;ny/=nl;nz/=nl;
  let diff=nx*lx+ny*ly+nz*lz; diff=Math.abs(diff);
  let sh=L.amb + (1-L.amb)*Math.pow(diff,0.9);
  // specular for foil
  if(L.spec>0){ const rzv=Math.pow(Math.max(0,diff),18); sh+=L.spec*rzv; }
  sh=Math.max(0.12,Math.min(1.5,sh));
  // pick paper vs hi/lo by shade, fiber noise
  const fib=0.96+0.06*fr(i*97+j*7);
  let col;
  const m=Math.min(1,sh);
  col=[ L.lo[0]+(L.hi[0]-L.lo[0])*m, L.lo[1]+(L.hi[1]-L.lo[1])*m, L.lo[2]+(L.hi[2]-L.lo[2])*m ];
  // blend toward base paper hue
  col=[ col[0]*0.5+L.paper[0]*0.5, col[1]*0.55+L.paper[1]*0.45, (col[2]*0.6+L.paper[2]*0.4)*fib ];
  if(!L.wire){
    fill(col[0], col[1]*100, Math.min(100,col[2]*100));
    beginShape(); vertex(ax,ay); vertex(bx,by); vertex(dx,dy); vertex(ex,ey); endShape(CLOSE);
  }
  // crease lines / mountain-valley coloring
  if(L.wire){
    const mtn=((i+j)&1)===0;
    stroke(L.crease[0], L.crease[1]*100, L.crease[2]*100, mtn?95:60);
    strokeWeight(mtn?Math.max(1.2,uMin*0.0016):Math.max(0.8,uMin*0.0011));
    if(!mtn) drawingContext.setLineDash([6,5]); else drawingContext.setLineDash([]);
    noFill(); beginShape(); vertex(ax,ay); vertex(bx,by); vertex(dx,dy); vertex(ex,ey); endShape(CLOSE);
  } else {
    stroke(L.crease[0], L.crease[1]*100, L.crease[2]*100, 40);
    strokeWeight(Math.max(0.6,uMin*0.0009)); noFill();
    line(ax,ay,bx,by); line(ax,ay,ex,ey);
  }
  noStroke();
}
if(L.wire) drawingContext.setLineDash([]);
if(P.alpha<100){ noStroke(); fill(L.lo[0],L.lo[1]*100,L.lo[2]*100,100-P.alpha); rect(0,0,width,height); }
pop();
